import { randomBytes, scrypt, timingSafeEqual } from 'crypto';

/**
 * Bot secrets in the config are stored as `scrypt$N$r$p$<salt>$<hash>` (base64), so a
 * copy of the config doesn't let anyone in as the bot. The secret itself is random and
 * generated by `node dist/bot-secret.js`; the hash never needs to be reversed.
 */
export interface SecretHash {
    N: number;
    r: number;
    p: number;
    salt: Buffer;
    hash: Buffer;
}

const DEFAULTS = { N: 16384, r: 8, p: 1 };
const HASH_LENGTH = 32;

function scryptAsync(secret: string, { N, r, p, salt }: Omit<SecretHash, 'hash'>, length: number): Promise<Buffer> {
    return new Promise((resolve, reject) => {
        scrypt(secret, salt, length, { N, r, p, maxmem: 256 * N * r }, (err, key) => (err ? reject(err) : resolve(key)));
    });
}

/** Parses a stored hash, or returns null for anything that isn't one (such as a bare secret). */
export function parseSecretHash(value: string): SecretHash | null {
    const parts = value.split('$');
    if (parts.length !== 6 || parts[0] !== 'scrypt') return null;
    const [N, r, p] = parts.slice(1, 4).map(Number);
    const salt = Buffer.from(parts[4], 'base64');
    const hash = Buffer.from(parts[5], 'base64');
    // Bounds keep a config typo from asking for gigabytes of memory per check.
    const powerOfTwo = Number.isInteger(N) && N >= 1024 && N <= 1 << 20 && (N & (N - 1)) === 0;
    if (!powerOfTwo || !Number.isInteger(r) || r < 1 || r > 32 || !Number.isInteger(p) || p < 1 || p > 16) return null;
    if (salt.length < 16 || hash.length < 16 || hash.length > 64) return null;
    return { N, r, p, salt, hash };
}

export async function hashSecret(secret: string): Promise<string> {
    const salt = randomBytes(16);
    const hash = await scryptAsync(secret, { ...DEFAULTS, salt }, HASH_LENGTH);
    return ['scrypt', DEFAULTS.N, DEFAULTS.r, DEFAULTS.p, salt.toString('base64'), hash.toString('base64')].join('$');
}

export async function verifySecret(secret: string, stored: SecretHash): Promise<boolean> {
    const actual = await scryptAsync(secret, stored, stored.hash.length);
    return timingSafeEqual(actual, stored.hash);
}

/** 256 random bits, URL-safe, so it fits a header and an environment variable as is. */
export const generateSecret = () => randomBytes(32).toString('base64url');
